import{z as i,x as s,o as E,c as d,q as r,j as B,D as e,d as a,s as A,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"notebook 工程","description":"","frontmatter":{"title":"notebook 工程","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-notebook-engineering.md","filePath":"quant/rc2-notebook-engineering.md","lastUpdated":1791413859000}'),p={name:"quant/rc2-notebook-engineering.md"};function b(k,o,D,m,c,h){const n=s("Mermaid");return E(),d("div",null,[o[2]||(o[2]=r('<h1 id="notebook-工程" tabindex="-1">notebook 工程 <a class="header-anchor" href="#notebook-工程" aria-label="Permalink to &quot;notebook 工程&quot;">​</a></h1><div class="epigraph"><p>notebook 的承诺是叙事与计算同页；它的代价是状态与叙述一样容易失序。重启重跑，是唯一诚实的校对。</p><footer>—— 据 Pimentel et al., Understanding and Improving the State of the Art in Notebook Reproducibility, 2019 与 Jupyter 社区的 restart-and-run-all 约定整理</footer></div><p><a href="/quant/rc2-code-standards">上一课</a>把研究代码钉在配置分离与纯函数计算核上，但研究的第一现场往往不是模块，是 notebook：数据在眼前、图在下一格、叙述顺手就写进 Markdown 单元。这份自由正是它的生产力和它的复现黑洞。本课写 notebook 的工程纪律：它只是驱动层，计算核仍在模块里；验收门只有一个——重启内核后从头跑通。守不住这一格，上一课的五条规范在 notebook 里全部作废。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>notebook 有两大病灶，都来自同一个根源：<strong>内核状态与文件内容是两个东西</strong>。其一，隐藏状态：你看到的代码是文件，变量却住在内核里——删掉一格重跑，旧变量还在；编号乱序地跑过一遍，图是旧代码画出来的。文件记录的实验和内核里跑过的实验，早就不是同一次。其二，巨型单体：加载、清洗、建模、画图长在一页里，跑通了，但没人敢动其中任何一格——一动就全页重跑，一动就断。于是 notebook 变成只进不出的圣物：能看，不能改，更不能重跑。Pimentel 等对公开 notebook 的研究用「重启后全部执行」检验，绝大多数经不起——「我这里能跑」与「任何人都能跑」之间隔着这一格。</p><p><span class="marginnote">术语翻译：「内核」是 notebook 背后那个真正执行代码的独立进程，你看到的页面只是它的一份聊天记录。可以把它想象成双开窗口：左边是代码文本，右边是一台还在运转的计算器——你删掉了左边的几行，右边计算器的屏幕上还留着结果；这份「记得」就是隐藏状态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="驱动层纪律" tabindex="-1">驱动层纪律 <a class="header-anchor" href="#驱动层纪律" aria-label="Permalink to &quot;驱动层纪律&quot;">​</a></h3><p>解法是把上一课的分层搬进 notebook：<strong>notebook 只做驱动与展示</strong>——读配置、调模块、画图、写叙述；加载与清洗、计算核都住在可导入的模块里，notebook 用 <code>import</code> 调用，不复制粘贴。参数注入用执行器（如 papermill）从外部配置生成 notebook，一份模板跑一批参数，而不是复制十个文件改十处路径。大表与模型产物落盘成文件，notebook 里只留引用与图，不把百兆数据帧留在输出里随文件一起提交。<strong>提交前清零编号</strong>：编号连续只说明你这次没乱跑，说明不了别人能跑通。</p>',9)),(E(),B(l,null,{default:e(()=>[A(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NB%5B%22notebook%20%E9%A9%B1%E5%8A%A8%E4%B8%8E%E5%B1%95%E7%A4%BA%22%5D%20--%3E%20IMP%5B%22import%20%E6%A8%A1%E5%9D%97%20%E8%AE%A1%E7%AE%97%E6%A0%B8%E5%9C%A8%E6%A8%A1%E5%9D%97%E9%87%8C%22%5D%0A%20%20PM%5B%22%E5%8F%82%E6%95%B0%E6%B3%A8%E5%85%A5%20papermill%22%5D%20--%3E%20NB%0A%20%20NB%20--%3E%20GATE%7B%22%E9%87%8D%E5%90%AF%E5%86%85%E6%A0%B8%20%E5%85%A8%E9%83%A8%E8%BF%90%E8%A1%8C%22%7D%0A%20%20GATE%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20CLR%5B%22%E6%B8%85%E9%9B%B6%E7%BC%96%E5%8F%B7%20%E6%8F%90%E4%BA%A4%22%5D%0A%20%20GATE%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20FIX%5B%22%E4%BF%AE%E8%A1%A5%20%E4%BD%BF%E7%8A%B6%E6%80%81%E5%9B%9E%E5%88%B0%E6%96%87%E4%BB%B6%E9%87%8C%22%5D%0A%20%20FIX%20--%3E%20GATE%0A"})]),fallback:e(()=>[...o[0]||(o[0]=[a(" Loading... ",-1)])]),_:1})),o[3]||(o[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),o[4]||(o[4]=t("p",null,"为什么唯一的门是重启重跑：它把「实验等于文件」这个假设强制兑现一次。内核态的任何依赖——残留在内存里的修正列、上次手动执行的那格改参——都会在重启后暴露为 NameError、旧图或静默不同的数字。失败是好事：它逼你把隐含依赖搬回文件，搬回模块，搬回配置。这正是上一课「显式性」约束在执行环境上的延续，只是检查从人眼换成了机器。",-1)),(E(),B(l,null,{default:e(()=>[A(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%BC%96%E8%BE%91%E5%B9%B6%E4%B9%B1%E5%BA%8F%E6%89%A7%E8%A1%8C%E8%8B%A5%E5%B9%B2%20cell%22%5D%20--%3E%20B%5B%22%E8%BE%93%E5%87%BA%E6%9D%A5%E8%87%AA%E5%86%85%E6%A0%B8%E6%80%81%20%E9%9D%9E%E6%96%87%E4%BB%B6%22%5D%0A%20%20B%20--%3E%20C%7B%22%E9%87%8D%E5%90%AF%E5%86%85%E6%A0%B8%20%E5%85%A8%E9%83%A8%E8%BF%90%E8%A1%8C%22%7D%0A%20%20C%20--%3E%20D%7B%22%E8%BE%93%E5%87%BA%E8%83%BD%E5%90%8C%E6%A0%B7%E5%A4%8D%E7%8E%B0%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E8%83%BD%22%7C%20E%5B%22%E5%AE%9E%E9%AA%8C%E7%A1%AE%E5%AE%9E%E7%AD%89%E4%BA%8E%E6%96%87%E4%BB%B6%22%5D%0A%20%20D%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20F%5B%22%E5%AD%98%E5%9C%A8%E5%8F%AA%E6%B4%BB%E5%9C%A8%E5%86%85%E6%A0%B8%E9%87%8C%E7%9A%84%E4%BE%9D%E8%B5%96%22%5D%0A%20%20F%20--%3E%20G%5B%22NameError%20%2F%20%E6%97%A7%E5%9B%BE%20%2F%20%E6%95%B0%E5%AD%97%E9%9D%99%E9%BB%98%E4%B8%8D%E5%90%8C%22%5D%0A%20%20G%20--%3E%20H%5B%22%E6%8A%8A%E9%9A%90%E5%90%AB%E4%BE%9D%E8%B5%96%E6%90%AC%E5%9B%9E%E6%A8%A1%E5%9D%97%20%E9%85%8D%E7%BD%AE%20%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...o[1]||(o[1]=[a(" Loading... ",-1)])]),_:1})),o[5]||(o[5]=r('<p><span class="marginnote">数字实例看参数注入：不用 papermill 时，跑 10 组参数通常复制 10 个 notebook、手改 10 处路径——漏改一处，就有两份「不同参数」的实验其实用的是同一组配置。用执行器则是一份模板加一份 10 行的参数清单，批量生成 10 份实例，路径错没错，看清单就行。</span></p><p>不这么做错在哪，量化场景有一类专属事故：notebook 里的探索结论（某因子窗口最优）被抄进正式代码，而 notebook 当时用了一个只在内核里存在的前处理步骤；三个月后复现包对不上基准，追查半天，死因是那格没保存的 cell。结论先行、代码后补，是 notebook 最贵的失败模式。台账接在后面：重启重跑通过的那次运行，才值得登记指纹与指标。</p><p><span class="marginnote">易错点：把「编号连续」当成「顺序正确」。乱序执行的文件可以恰好编号连续，只要那是在乱跑之后一次性提交的；唯一可信的证词是提交前那一次「重启并全部运行」，编号从 1 开始且一路通过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>notebook 不必消灭：探索期的乱序快跑是它的正当用途，本课约束的是<strong>被引用的时刻</strong>——结论进文档、进汇报、进台账之前，那一页必须过重启重跑的门，与上一课「被引用的草稿没有豁免权」同一条款。也不是所有计算都该塞进模块：一次性的一行统计、一格画图诊断，留在 notebook 里比新建模块更诚实。真正的边界在于：凡是别人需要重跑的东西（计算核、参数、数据路径），不许只活在内核里。可视化诊断的更多手法，回测框架一侧另有专课，本课不展开。</p><p><span class="marginnote">常见误区：初学者容易以为工程纪律要求「每页 notebook 随时保持可重跑」，于是探索期也战战兢兢。实际约束点只有一个——被引用的时刻：乱跑十遍都没关系，只要结论要进文档或台账前，那一页重启跑通并清零编号；平时草稿的自由，正是 notebook 存在的理由。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>notebook 的根源病灶：内核状态与文件内容是两个东西；文件记录的不一定是内核跑过的实验。</li><li>驱动层纪律：notebook 只做驱动与展示，计算核在模块里，参数用执行器注入。</li><li>唯一验收门是重启内核后全部运行；通过才允许提交，提交前清零编号。</li><li>大产物落盘留引用，别把数据帧存进输出；结论抄进正式代码前，先确认依据可重跑。</li><li>出处：Pimentel et al., 2019 对 notebook 复现率的实证；Jupyter 社区 restart-and-run-all 约定；站内<a href="/quant/rc2-code-standards">研究代码的规范</a>一课。</li></ul>',8))])}const g=i(p,[["render",b]]);export{C as __pageData,g as default};
